window.kbPageData["views/entry/k-87ad3280ba303147"] = {"key":"entry/k-87ad3280ba303147","state":{"route":"entry/k-87ad3280ba303147"},"node":{"id":"k-87ad3280ba303147","mode":"k","title":"工作量、工作效率与时间","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["工作量等于效率乘时间，协作效率为各效率之和","恒定效率下，工作量等于工作效率乘以时间，合做效率等于各人效率之和"],"qs":["江苏 2024 C类 行测#61","江苏 2025 C类 行测#61"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"工作效率恒定时，工作量等于工作效率乘以工作时间。多方同时作业且各自完成的工作量可以相加时，合计效率等于各方效率之和。","review":{"definition":"工作效率恒定时，工作量等于工作效率乘以工作时间。多方同时作业且各自完成的工作量可以相加时，合计效率等于各方效率之和。","explanation":"设两架无人机每小时的工作量分别为 M、N。先后作业完成整片农田，工作量为2M+5N。合做1小时完成三分之一，所以3(M+N)=2M+5N，得 M=2N。以 N 为1个工作量单位每小时，整片农田的工作量为9个单位，M 单独完成需9÷2=4.5小时。","references":[],"evidence":"两架无人机同时工作1小时后，有三分之二的农田尚未喷洒","disposition":"独立词条","basis":"据原题和解析编释。","title":"工作量、工作效率与时间","related":[],"examFocus":{"江苏 2024 C类 行测#61":"用工作量等于效率乘时间，比较乙独做和甲乙合做的累计工作量与丙完成的剩余工作量。","江苏 2025 C类 行测#61":"用工作量等于效率乘时间，把两机先后喷完整片农田的总工作量与合做一小时的已完成工作量联系起来。"}},"readings":[{"origin":"k-87ad3280ba303147","title":"工作量、工作效率与时间","qs":["江苏 2025 C类 行测#61"],"definition":"工作效率恒定时，工作量等于工作效率乘以工作时间。多方同时作业且各自完成的工作量可以相加时，合计效率等于各方效率之和。","explanation":"设两架无人机每小时的工作量分别为 M、N。先后作业完成整片农田，工作量为2M+5N。合做1小时完成三分之一，所以3(M+N)=2M+5N，得 M=2N。以 N 为1个工作量单位每小时，整片农田的工作量为9个单位，M 单独完成需9÷2=4.5小时。","evidence":"两架无人机同时工作1小时后，有三分之二的农田尚未喷洒","doubt":"","references":[]},{"origin":"k-93f338f228045428","title":"工作量、工作效率与时间","qs":["江苏 2024 C类 行测#61"],"definition":"效率恒定时，工作量等于工作效率乘以工作时间。多人同时工作且各自效率保持不变、完成的工作量可以相加时，合做效率等于各人效率之和。","explanation":"设甲、乙、丙的效率分别为a、b、c。乙单做9天、再与甲合做6天，完成的工作量为9b＋6(a＋b)，占总量的60%。丙10天完成剩下的40%，工作量为10c。两段工作量之比为3∶2，化简得2a＋5b＝5c。只有A项的5∶4∶6满足这个关系。","evidence":"9×乙+6×（甲+乙）=60%×工作总量","doubt":"","references":[]}]},"questions":{"江苏 2024 C类 行测#61":{"paper":"江苏 2024 C类 行测","n":61,"mod":"数量关系","src":["3f1ec77ae8a18519b57e.pdf",10],"asrc":["02d6b49839583bdaf297.pdf",17],"card":"4f1115f40753da3857970846","links":[{"id":"k-87ad3280ba303147","role":"解题依据","why":"将乙单做和甲乙合做两个阶段分别换算为工作量后相加。"}]},"江苏 2025 C类 行测#61":{"paper":"江苏 2025 C类 行测","n":61,"mod":"数量关系","src":["ffc394a1c160f331ec57.pdf",13],"asrc":["d1de3b437151c05b769e.pdf",18],"card":"f54d5d677609c366b52ddc4f","links":[{"id":"k-87ad3280ba303147","role":"解题依据","why":"同时作业的已完成份额由两架无人机的效率之和与协作时间决定。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-87ad3280ba303147":[["江苏 2024 C类 行测#61"],["江苏 2025 C类 行测#61"]]}};
